_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triplet_margin_loss_kernel")

class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks
    using a single custom PTX kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        assert anchor.is_cuda and positive.is_cuda and negative.is_cuda
        assert anchor.dtype == torch.float32
        assert anchor.shape == positive.shape == negative.shape

        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()

        batch_size, dim = anchor.shape

        output = torch.zeros((), device=anchor.device, dtype=torch.float32)

        module = _get_ptx_module()

        module.launch(
            "triplet_margin_loss_kernel",
            grid=(min(batch_size, 384), 1, 1),
            block=(512, 1, 1),
            arguments=[
                anchor,
                positive,
                negative,
                output,
                i32(batch_size),
                i32(dim),
                f32(self.margin),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )

        return output

